SELECT p.id AS position_id, s.interval_code, s.id, s.candle_open_time, s.generated_at, s.decision, s.total_score, s.confidence_score, s.latest_price FROM paper_position p JOIN trade_signal s ON s.symbol=p.symbol AND s.interval_code IN ('5m','1h') AND s.generated_at BETWEEN p.opened_at - INTERVAL 15 MINUTE AND p.closed_at + INTERVAL 1 MINUTE WHERE p.id IN (182,172,162,158,143,137) ORDER BY p.id, s.interval_code, s.generated_at LIMIT 300